ui.css:
.frame { border: 2px solid #4d5266; outline: 2px solid #06070b; box-shadow: inset 0 0 0 2px #06070b, inset 0 2px 0 2px #1a1c28, 0 4px 0 2px rgba(0,0,0,.45); border-radius: 0; }
.bar-top { height: 14px; background: #0b0c13; position: relative; overflow: hidden; }
.bar-top-fill { height: 100%; background: linear-gradient(#c8fff0 0 2px, #5fd8bc 2px 6px, #2a9688 6px 9px, #17565a 9px); }
.bar-top::after { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 30px, rgba(6,7,11,.75) 30px 32px); }
.bar-red { width: 236px; height: 18px; background: #16070b; }
.bar-red-fill { height: 100%; background: linear-gradient(#ffb0a0 0 2px, #d8343c 2px 8px, #9a1822 8px 12px, #5c0c14 12px); }
.clock { padding: 4px 32px 6px; background: linear-gradient(#141624, #090a10); clip-path: polygon(0 10px, 10px 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%); }
.clock-time { font: 400 28px/1.1 'Silkscreen', monospace; color: #e8eefa; letter-spacing: 2px; text-shadow: 3px 3px 0 #000, 0 0 12px rgba(150,180,255,.35); }
.clock-label { font: 400 17px/1 'UnifrakturMaguntia', 'Pirata One', serif; color: #f0a850; text-shadow: 2px 2px 0 #000, 0 0 8px rgba(255,140,40,.4); }
.card { border: 3px solid #a8874c; outline: 3px solid #06070b; box-shadow: inset 0 0 0 3px #0b0a10, inset 0 0 0 5px #5a4628, 0 14px 30px rgba(0,0,0,.75); background: radial-gradient(ellipse at 50% 32%, #2e2848 0, #18152a 45%, #0b0a12 100%); image-rendering: pixelated; }
